import{_ as l,a0 as p,w as o,s as d,ao as h,I as t,x as e,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在 Debian/Ubuntu 系統中檢查程序包是否安裝？ | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Debian/Ubuntu 系統中檢查程序包是否安裝？ | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Debian/Ubuntu 系統中檢查程序包是否安裝？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Debian/Ubuntu 系統中檢查程序包是否安裝？ | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190513 How To Check Whether The Given Package Is Installed Or Not On Debian-Ubuntu System","title":"如何在 Debian/Ubuntu 系統中檢查程序包是否安裝？","tag":"201906","desc":""},"relativePath":"201906/20190513 How To Check Whether The Given Package Is Installed Or Not On Debian-Ubuntu System.md","filePath":"[post].md"}'),r={name:"201906/20190513 How To Check Whether The Given Package Is Installed Or Not On Debian-Ubuntu System.md"};function c(g,a,u,b,k,m){const s=p("Link");return o(),d("div",null,[a[15]||(a[15]=h(`<h1 id="如何在-debian-ubuntu-系統中檢查程序包是否安裝" tabindex="-1">如何在 Debian/Ubuntu 系統中檢查程序包是否安裝？ <a class="header-anchor" href="#如何在-debian-ubuntu-系統中檢查程序包是否安裝" aria-label="Permalink to “如何在 Debian/Ubuntu 系統中檢查程序包是否安裝？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201906/23/235541yl41p73z5jv78y8p.jpg" alt=""></p><p>我們近期發佈了一篇關於批量程序包安裝的文章。在此同時，關於如何獲取系統上已安裝了的程序包信息，我也做了些調查然後找到了些方法。我會把這些方法分享在我們的網站上，希望能幫助到其他人。</p><p>有很多種方法可以檢查程序包是否已安裝，我找到了 7 種命令，你可以從中選擇你喜歡的使用。</p><p>如下：</p><ul><li><code>apt-cache</code>：可用於查詢 APT 緩存或程序包的元數據。</li><li><code>apt</code>：是基於 Debian 的系統中的安裝、下載、刪除、搜索和管理包的強有力的工具。</li><li><code>dpkg-query</code>：一個查詢 dpkg 資料庫的工具。</li><li><code>dpkg</code>：基於 Debian 的系統的包管理工具。</li><li><code>which</code>：返回在終端中輸入命令時執行的可執行文件的全路徑。</li><li><code>whereis</code>：可用於搜索指定命令的二進制文件、源碼文件和幫助文件。</li><li><code>locate</code>：比 <code>find</code> 命令快，因為其使用 <code>updatedb</code> 資料庫搜索，而 <code>find</code>命令在實際系統中搜索。</li></ul><h3 id="方法一、使用-apt-cache-命令" tabindex="-1">方法一、使用 apt-cache 命令 <a class="header-anchor" href="#方法一、使用-apt-cache-命令" aria-label="Permalink to “方法一、使用 apt-cache 命令”">​</a></h3><p><code>apt-cache</code> 命令用於從 APT 內部資料庫中查詢<strong>APT 緩存</strong>和<strong>包的元數據</strong>，將會搜索和顯示指定包的信息，包括是否安裝、程序包版本、源碼倉庫信息等。</p><p>下面的示例清楚的顯示 <code>nano</code> 包已經在系統中安裝了以及對應安裝的版本號。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-cache policy nano</span></span>
<span class="line"><span>nano:</span></span>
<span class="line"><span>  Installed: 2.9.3-2</span></span>
<span class="line"><span>  Candidate: 2.9.3-2</span></span>
<span class="line"><span>  Version table:</span></span>
<span class="line"><span> *** 2.9.3-2 500</span></span>
<span class="line"><span>        500 http://in.archive.ubuntu.com/ubuntu bionic/main amd64 Packages</span></span>
<span class="line"><span>        100 /var/lib/dpkg/status</span></span></code></pre></div><h3 id="方法二、使用-apt-命令" tabindex="-1">方法二、使用 apt 命令 <a class="header-anchor" href="#方法二、使用-apt-命令" aria-label="Permalink to “方法二、使用 apt 命令”">​</a></h3><p><code>apt</code> 是一個功能強大的命令列工具，可用於安裝、下載、刪除、搜索、管理程序包以及查詢關於程序包的信息，類似對於 <code>libapt-pkg</code> 庫的所有功能的底層訪問。其包含一些與包管理相關的但很少用到的命令列功能。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt -qq list nano</span></span>
<span class="line"><span>nano/bionic,now 2.9.3-2 amd64 [installed]</span></span></code></pre></div><h3 id="方法三、使用-dpkg-query-命令" tabindex="-1">方法三、使用 dpkg-query 命令 <a class="header-anchor" href="#方法三、使用-dpkg-query-命令" aria-label="Permalink to “方法三、使用 dpkg-query 命令”">​</a></h3><p><code>dpkg-query</code> 是顯示 <code>dpkg</code> 資料庫中程序包信息列表的一個工具。</p><p>下面示例中的輸出的第一列 <code>ii</code>，表示查詢的程序包已安裝了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dpkg-query --list | grep -i nano</span></span>
<span class="line"><span>ii  nano    2.9.3-2    amd64    small, friendly text editor inspired by Pico</span></span></code></pre></div><h3 id="方法四、使用-dpkg-命令" tabindex="-1">方法四、使用 dpkg 命令 <a class="header-anchor" href="#方法四、使用-dpkg-命令" aria-label="Permalink to “方法四、使用 dpkg 命令”">​</a></h3><p><code>dpkg</code>（<strong>d</strong>ebian <strong>p</strong>ac<strong>k</strong>a<strong>g</strong>e）是一個安裝、構建、刪除和管理 Debian 包的工具，但和其他包管理系統不同的是，其不能自動下載和安裝包或包依賴。</p><p>下面示例中的輸出的第一列 <code>ii</code>，表示查詢的包已安裝了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dpkg -l | grep -i nano</span></span>
<span class="line"><span>ii  nano     2.9.3-2    amd64   small, friendly text editor inspired by Pico</span></span></code></pre></div><h3 id="方法五、使用-which-命令" tabindex="-1">方法五、使用 which 命令 <a class="header-anchor" href="#方法五、使用-which-命令" aria-label="Permalink to “方法五、使用 which 命令”">​</a></h3><p><code>which</code> 命令返回在終端中輸入命令時執行的可執行文件的全路徑。這對於你想要給可執行文件創建桌面快捷方式或符號鏈接時非常有用。</p><p><code>which</code> 命令僅在當前用户 <code>PATH</code> 環境變量配置的目錄列表中搜索，而不是在所有用户的目錄中搜索。這意思是當你登入你自己賬號時，其不會在 <code>root</code> 用户文件或目錄中搜索。</p><p>如果對於指定的程序包或可執行文件路徑有如下輸出，則表示已安裝了，否則沒有。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># which nano</span></span>
<span class="line"><span>/bin/nano</span></span></code></pre></div><h3 id="方法六、使用-whereis-命令" tabindex="-1">方法六、使用 whereis 命令 <a class="header-anchor" href="#方法六、使用-whereis-命令" aria-label="Permalink to “方法六、使用 whereis 命令”">​</a></h3><p><code>whereis</code> 命令用於針對指定命令搜索對應的程序二進制文件、源碼文件以及幫助文件等。</p><p>如果對於指定的程序包或可執行文件路徑有如下輸出，則表示已安裝了，否則沒有。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># whereis nano</span></span>
<span class="line"><span>nano: /bin/nano /usr/share/nano /usr/share/man/man1/nano.1.gz /usr/share/info/nano.info.gz</span></span></code></pre></div><h3 id="方法七、使用-locate-命令" tabindex="-1">方法七、使用 locate 命令 <a class="header-anchor" href="#方法七、使用-locate-命令" aria-label="Permalink to “方法七、使用 locate 命令”">​</a></h3><p><code>locate</code> 命令比 <code>find</code> 命令快，因為其在 <code>updatedb</code> 資料庫中搜索，而 <code>find</code> 命令在實際系統中進行搜索。</p><p>對於獲取指定文件，其使用資料庫而不是在特定目錄路徑中搜索。</p><p><code>locate</code> 命令不會預安裝在大多數系統中，需要手動安裝。</p><p><code>locate</code> 使用的資料庫會根據定時任務定期更新。當然，我們也可以手動更新。</p><p>如果對於指定的程序包或可執行文件路徑有如下輸出，則表示已安裝了，否則沒有。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># locate --basename &#39;\\nano&#39;</span></span>
<span class="line"><span>/usr/bin/nano</span></span>
<span class="line"><span>/usr/share/nano</span></span>
<span class="line"><span>/usr/share/doc/nano</span></span></code></pre></div><hr>`,38)),t("p",null,[a[1]||(a[1]=e("via: ",-1)),n(s,{href:"https://www.2daygeek.com/how-to-check-whether-the-given-package-is-installed-or-not-on-ubuntu-debian-system/"},{default:i(()=>[...a[0]||(a[0]=[e("https://www.2daygeek.com/how-to-check-whether-the-given-package-is-installed-or-not-on-ubuntu-debian-system/",-1)])]),_:1})]),t("p",null,[a[6]||(a[6]=e("作者：",-1)),n(s,{href:"https://www.2daygeek.com/author/magesh/"},{default:i(()=>[...a[2]||(a[2]=[e("Magesh Maruthamuthu",-1)])]),_:1}),a[7]||(a[7]=e(" 選題：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[3]||(a[3]=[e("lujun9972",-1)])]),_:1}),a[8]||(a[8]=e(" 譯者：",-1)),n(s,{href:"https://github.com/yizhuoyan"},{default:i(()=>[...a[4]||(a[4]=[e("yizhuoyan",-1)])]),_:1}),a[9]||(a[9]=e(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:i(()=>[...a[5]||(a[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[a[12]||(a[12]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原創編譯，",-1)),n(s,{href:"https://linux.cn/"},{default:i(()=>[...a[11]||(a[11]=[e("Linux中國",-1)])]),_:1}),a[14]||(a[14]=e(" 榮譽推出",-1))])])}const C=l(r,[["render",c]]);export{w as __pageData,C as default};
